test('renderInvoiceText format with all features', () => {
  const draftInvoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [
      { sku: 'STICKER', qty: 50, discountPercent: 5 },
    ],
    terms: 'NET30',
  }).value;

  const withVoucher = applyVoucher(draftInvoice, { code: 'TEST', amount: 100 }).value;
  const issuedInvoice = issueInvoice(withVoucher, []).value;
  const paidInvoice = recordPayment(issuedInvoice, { amount: 500, date: '2026-10-05' }).value;

  const text = renderInvoiceText(paidInvoice);

  // Check all sections are present
  assert(text.includes('INV-'));
  assert(text.includes('Sticker sheet'));
  assert(text.includes('Discount:'));
  assert(text.includes('Voucher:'));
  assert(text.includes('Total:'));
  assert(text.includes('Due:'));
  assert(text.includes('Paid:'));

  // Verify structure (invoice number should come before everything else)
  const lines = text.split('\n');
  assert(lines[0].includes('INV-'));
  assert(lines[lines.length - 1].includes('Paid:'));
});
